import sys

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        print(0)
        return

    N = int(data[0].strip())
    if N <= 0:
        print(0)
        return

    grid = []
    for i in range(1, N + 1):
        if i < len(data):
            row = data[i].strip()
        else:
            row = ""
        cells = row.split(',')
        grid.append(cells)

    if len(grid) < N or any(len(row) < N for row in grid):
        print(0)
        return

    reachable = [[False] * N for _ in range(N)]
    reachable[N-1][N-1] = True

    for r in range(N-1, -1, -1):
        for c in range(N-1, -1, -1):
            if not reachable[r][c]:
                continue

            cell_val = grid[r][c]
            if cell_val == 'F':
                continue
            elif cell_val == 'D':
                continue
            else:
                dirs = set(cell_val)

            if r > 0:
                if 'N' in dirs and not reachable[r-1][c]:
                    if grid[r-1][c] != 'D':
                        reachable[r-1][c] = True

            if r < N - 1:
                if 'S' in dirs and not reachable[r+1][c]:
                    if grid[r+1][c] != 'D':
                        reachable[r+1][c] = True

            if c > 0:
                if 'W' in dirs and not reachable[r][c-1]:
                    if grid[r][c-1] != 'D':
                        reachable[r][c-1] = True

            if c < N - 1:
                if 'E' in dirs and not reachable[r][c+1]:
                    if grid[r][c+1] != 'D':
                        reachable[r][c+1] = True

    count = 0
    for c in range(N):
        if reachable[0][c]:
            count += 1
    for r in range(1, N):
        if reachable[r][0]:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
